(1007453, -1, 50, -382, 0, 0, 4096, 375250, 1500, 0, 'Dishonest Intentions: Leatherworker''s Satchel', 'Collect 1 Leatherworker''s Satchel', 'Animal rights groups are "concerned" with how we acquire our pelts...$b$bWe need your help heroes. It may be menial work, animal rights groups are harassing us about how we acquire our pelts, but that isn''t important right now. What''s important is that I need you to collect some pelts for me!$b$bCollect 1 Leatherworker''s Satchel. Naturally, you will be handsomely rewarded for your assistance, hero.', '', 'Return to the call board.', 0, 0, 0, 0, 0, 0, 0, 0, 34482, 1, '', '', '', ''),
(1007496, -1, 50, -382, 0, 0, 4096, 375250, 1500, 0, 'Natural Blend: Adept''s Elixir', 'Collect 4 Adept''s Elixir', 'Seems we are out of herbs for our latest blend...$b$bWe need your help heroes. It may be menial work, but we ran out of herbs for our latest blend! We make all natural herb blends with absolutely no added flavors! However, our latest herb blend seems to be selling out fast, and we are running out of supplies to make more of it! Do you think you could do us a favor?$b$bCollect 4 Adept''s Elixir. Naturally, you will be handsomely rewarded for your assistance, hero.', '', 'Return to the call board.', 0, 0, 0, 0, 0, 0, 0, 0, 28103, 4, '', '', '', ''),
